# Purpose: Switch-Break — General-purpose PowerShell utilities.
# switch can iterate an array/collection/pipeline AND be told to halt. $SinceWhen = "TODAY","YESTERDAY","LOGIN","BOOT" Switch ($SinceWhen | Sort-Object) {   "BOOT"      {                  $OS = Get-CIMinstance Win32_OperatingSystem                 $sinceTime = $OS.LastBootUpTime                 Write-Output "Boot $sinceTime"               }   "LOGIN"     {                 $loginSession = Get-CIMinstance -class Win32_LogonSession                 $sinceTime = $loginSession.StartTime                 Write-Output "Login $SinceTime"               }   "TODAY"     {                 $sinceTime = (Get-Date)-(Get-Date).timeofday                 Write-Output "Today $sinceTime"               }   "YESTERDAY" {                 $sinceTime = ((Get-Date)-(Get-Date).timeofday).AddDays(-1)                 Write-Output "Yesterday $sinceTime"               } }# what happens if I add a ";Break" to one of the matches?